import {workspaceState,canEdit,workspaceRequest,workspacePost,initWorkspaceLogin,setCurrentProject,loadProjects,saveProject,updateSaveState} from './workspace-client.js';
import {workflowSnapshot,loadWorkflowSnapshot} from './workflow.js';
import {snapshotForSave,validateSnapshot} from './project-snapshots.js';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let details={assignee:'',approver:'',deadline:'',publications:[],evidence:[]},history=[],last='',timer=null,saving=false,again=false,paused=false,restoring=false,dirty=false;
export function projectDetails(){return structuredClone(details);}
export function setProjectDetails(next){details={...details,...next};schedule();}
function capture(){const {run,input}=workflowSnapshot();return snapshotForSave(input,run);}
function schedule(){if(restoring)return;const current=capture(),key=JSON.stringify({current,details});if(key===last)return;last=key;dirty=true;if(current.input.topic||current.run){history.push({time:new Date().toISOString(),snapshot:current});history=history.slice(-30);}if(!workspaceState().user||!canEdit()||paused)return;updateSaveState('保存中…');clearTimeout(timer);timer=setTimeout(()=>{timer=null;void persist();},1200);}
async function persist(){if(saving){again=true;return;}if(paused||!workspaceState().user||!canEdit())return;saving=true;const snapshot=capture(),info=structuredClone(details),savingKey=JSON.stringify({current:snapshot,details:info});try{await saveProject(snapshot,info);dirty=savingKey!==JSON.stringify({current:capture(),details});}catch(e){paused=e.code==='save_conflict';updateSaveState(e.message);}finally{saving=false;if(again){again=false;void persist();}}}
async function open(project){if(workflowSnapshot().busy)throw Error('制作を停止してから別の記事を開いてください。');if(saving)throw Error('保存が終わってから開いてください。');if(dirty&&!confirm('画面に残っている変更は保存されていません。必要な原稿を書き出してから、保存済みの記事を開いてください。開きますか？'))return;clearTimeout(timer);timer=null;const list=await workspaceRequest('/api/workspace/members?id='+project.id),user=workspaceState().user;const role=project.owner_id===user.id?'owner':list.find(m=>m.email===user.email)?.role||'viewer';restoring=true;try{loadWorkflowSnapshot(validateSnapshot(project.snapshot));details={assignee:'',approver:'',deadline:'',publications:[],evidence:[],...project.details};setCurrentProject(project,role);history=[];last='';paused=false;dirty=false;updateSaveState('保存した記事を開きました');}finally{restoring=false;}window.dispatchEvent(new Event('project:opened'));}
export async function openProject(id){const rows=await workspaceRequest('/api/workspace/project?id='+id);if(!rows?.[0])throw Error('この記事を開く権限がありません。');await open(rows[0]);}
async function showProjects(){const dialog=$('projects-dialog');$('projects-message').textContent='';dialog.showModal();try{const state=workspaceState();if(!state.user){$('project-list').innerHTML='<p>記事を保存して次回も開くには、ログインしてください。</p>';return;}const projects=await loadProjects();$('project-list').innerHTML=projects.length?projects.map(p=>`<button class="project-list-row" data-project-id="${p.id}"><strong>${esc(p.title)}</strong><span>${esc(p.details?.deadline||'期限未設定')}</span><small>${new Date(p.updated_at).toLocaleString('ja-JP')}</small></button>`).join(''):'<p>保存した記事はまだありません。</p>';for(const b of $('project-list').querySelectorAll('[data-project-id]'))b.onclick=async()=>{try{await openProject(b.dataset.projectId);dialog.close();}catch(e){$('projects-message').textContent=e.message;}};}catch(e){$('projects-message').textContent=e.message;}}
async function showHistory(){const dialog=$('history-dialog');$('history-preview').textContent='';dialog.showModal();let versions=history.map((v,i)=>({id:String(i),label:new Date(v.time).toLocaleString('ja-JP'),snapshot:v.snapshot}));if(workspaceState().current){const rows=await workspaceRequest('/api/workspace/versions?id='+workspaceState().current.id);versions=rows.map(v=>({id:v.id,label:'保存 '+v.revision+' · '+new Date(v.created_at).toLocaleString('ja-JP')}));}$('history-list').innerHTML=versions.map(v=>`<button class="button secondary" data-version="${v.id}">${esc(v.label)}</button>`).join('')||'<p>編集すると履歴が表示されます。</p>';for(const b of $('history-list').querySelectorAll('[data-version]'))b.onclick=async()=>{try{const v=versions.find(v=>v.id===b.dataset.version),snapshot=v.snapshot||((await workspaceRequest('/api/workspace/version?id='+v.id))[0]?.snapshot);const checked=validateSnapshot(snapshot);const old=checked.run?.agents.find(a=>a.id==='rewrite')?.output||checked.run?.agents.find(a=>a.id==='writing')?.output;const current=workflowSnapshot().run?.agents.find(a=>a.id==='rewrite')?.output;const panel=$('history-preview');panel.innerHTML=`<div class="comparison-grid"><section><h3>選んだ履歴</h3><pre>${esc(old?.article||checked.input.topic)}</pre></section><section><h3>現在の内容</h3><pre>${esc(current?.article||workflowSnapshot().input.topic)}</pre></section></div><button id="history-restore" class="button primary" ${!canEdit()?'disabled':''}>この内容に戻す</button>`;$('history-restore').onclick=()=>{if(workflowSnapshot().busy||!canEdit())return;if(!confirm('この履歴に戻しますか？ 公開前の確認はやり直します。'))return;loadWorkflowSnapshot(checked);dialog.close();last='';schedule();};}catch(e){$('history-preview').textContent=e.message;}};}
async function showTeam(){const dialog=$('project-team-dialog');$('team-assignee').value=details.assignee||'';$('team-approver').value=details.approver||'';$('team-deadline').value=details.deadline||'';$('team-message').textContent='';dialog.showModal();$('team-save').disabled=!canEdit();$('member-add').disabled=workspaceState().role!=='owner'||!workspaceState().current;try{const members=workspaceState().current?await workspaceRequest('/api/workspace/members?id='+workspaceState().current.id):[];$('member-list').textContent=members.map(m=>m.email+' · '+({viewer:'閲覧のみ',editor:'編集担当',approver:'承認担当'}[m.role])).join('\n')||'保存した記事には、閲覧・編集・承認の担当者を追加できます。';}catch(e){$('team-message').textContent=e.message;}}
async function notices(){if(!workspaceState().user)return;try{const rows=await workspaceRequest('/api/workspace/notices');$('saved-notices').innerHTML=rows.map(n=>`<button class="project-list-row" data-saved-notice="${n.id}" data-project="${n.project_id}"><strong>${n.kind==='review'?'記事の確認をお願いします':'記事の期限が近づいています'}</strong><small>${n.read_at?'確認済み':'未確認'}</small></button>`).join('');for(const b of $('saved-notices').querySelectorAll('[data-saved-notice]'))b.onclick=async()=>{await openProject(b.dataset.project);await workspacePost('/api/workspace/read',{id:b.dataset.savedNotice});$('projects-dialog').close();};const due=rows.filter(n=>!n.read_at);$('saved-notice-count').textContent=due.length?'対応待ち '+due.length+'件':'';}catch{/* Existing local notices remain available. */}}
export async function initProjectWorkspace(){await initWorkspaceLogin();$('projects-open').onclick=()=>void showProjects();$('history-open').onclick=()=>void showHistory();$('project-team-open').onclick=()=>void showTeam();$('project-save-now').onclick=async()=>{paused=false;await persist();};$('project-new').onclick=()=>{if(workflowSnapshot().busy||saving)return;if(!confirm('新しい記事を始めますか？ 未保存の内容は先に保存してください。'))return;clearTimeout(timer);restoring=true;setCurrentProject(null);loadWorkflowSnapshot({version:1,input:{topic:'',audience:'',goal:'',media:'ビジネスメディア',targetLength:1500,sources:'',rules:'',transcript:'',metrics:'',webSearch:false},run:null});details={assignee:'',approver:'',deadline:'',publications:[],evidence:[]};setCurrentProject(null);history=[];last='';dirty=false;paused=false;restoring=false;$('projects-dialog').close();};$('project-delete').onclick=async()=>{const current=workspaceState().current;if(!current||workspaceState().role!=='owner'||!confirm('この記事と保存した履歴を削除しますか？'))return;try{await workspacePost('/api/workspace/delete',{id:current.id});clearTimeout(timer);timer=null;restoring=true;setCurrentProject(null);details={assignee:'',approver:'',deadline:'',publications:[],evidence:[]};loadWorkflowSnapshot({version:1,input:{topic:'',audience:'',goal:'',media:'ビジネスメディア',targetLength:1500,sources:'',rules:'',transcript:'',metrics:'',webSearch:false},run:null});history=[];last='';dirty=false;paused=false;restoring=false;$('projects-dialog').close();}catch(e){$('projects-message').textContent=e.message;}};$('team-save').onclick=()=>{if(!canEdit())return;details={...details,assignee:$('team-assignee').value.trim().toLowerCase(),approver:$('team-approver').value.trim().toLowerCase(),deadline:$('team-deadline').value};schedule();$('project-team-dialog').close();};$('member-add').onclick=async()=>{try{const p=workspaceState().current;if(!p)throw Error('先に記事を保存してください。');await workspacePost('/api/workspace/member',{id:p.id,email:$('member-email').value.trim(),role:$('member-role').value});await showTeam();$('team-message').textContent='担当者を追加しました。';}catch(e){$('team-message').textContent=e.message;}};window.addEventListener('production:updated',schedule);document.addEventListener('input',e=>{if(e.target.id.startsWith('wf-'))schedule();});window.addEventListener('workspace:changed',()=>{const s=workspaceState();$('project-save-now').disabled=!s.user||!canEdit();$('project-delete').disabled=!s.current||s.role!=='owner';if(!s.user)updateSaveState('画面内で作業中');if($('save-policy-note'))$('save-policy-note').textContent=s.user?'記事は自動保存されます。担当者だけが閲覧できます。':'必要な原稿は保存してください。ログインすると記事を保存できます。';void notices();});window.addEventListener('beforeunload',e=>{if(saving||dirty||timer&&workspaceState().user){e.preventDefault();e.returnValue='';}});setInterval(()=>void notices(),60000);window.dispatchEvent(new Event('workspace:changed'));void notices();}
